CREATE TRIGGER agent_profiles_seed_conflict BEFORE INSERT ON agent_profiles
WHEN EXISTS (SELECT 1 FROM agent_profiles existing WHERE existing.id = NEW.id AND existing.version = NEW.version AND (existing.seed_order <> NEW.seed_order OR existing.config_sha256 <> NEW.config_sha256 OR existing.config_json <> NEW.config_json OR existing.enabled <> 0 OR existing.execution_mode <> 'skeleton'))
BEGIN SELECT RAISE(ABORT, 'SEED_CONFLICT'); END;

