CREATE TABLE migration_seed_verify (id INTEGER PRIMARY KEY);
CREATE TRIGGER migration_seed_verify_guard BEFORE INSERT ON migration_seed_verify
WHEN (SELECT COUNT(*) FROM agent_profiles WHERE id IN ('atlas','nova','miro','aegis','ledger','forge','luma','iris','verify','sentinel','archon','orion','helios','regula','insight','keystone','nexus','arca') AND version = 1 AND enabled = 0 AND execution_mode = 'skeleton') <> 18
BEGIN SELECT RAISE(ABORT, 'SEED_MANIFEST_INCOMPLETE'); END;
INSERT INTO migration_seed_verify (id) VALUES (1);
DROP TRIGGER migration_seed_verify_guard;
DROP TABLE migration_seed_verify;
